export async function main(city: string) {
  const geo = await (
    await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city)}&count=1`)
  ).json()
  const place = geo.results?.[0]
  if (!place) throw new Error(`No city named ${city}`)
  const forecast = await (
    await fetch(
      `https://api.open-meteo.com/v1/forecast?latitude=${place.latitude}&longitude=${place.longitude}&current=temperature_2m,wind_speed_10m,weather_code`
    )
  ).json()
  return { city: place.name, country: place.country, ...forecast.current }
}
